LOGO_B64 = ""
INDEX_HTML = '<!DOCTYPE html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no">\n<title>Mini App</title>\n<link rel="icon" href="/logo.jpg">\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<style>\n:root{--bg:#0a1238;--bg2:#0e1a4d;--card:#111f58;--line:#1d3180;--b1:#1e6bff;--b2:#1e9bff;--c:#38e8ff;--tx:#eaf1ff;--mut:#8fa3dd;--ok:#2ee59d;--bad:#ff5d7a;\n--grad:linear-gradient(135deg,#1e6bff,#38e8ff)}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;background:var(--bg);color:var(--tx);font-family:system-ui,-apple-system,"Segoe UI",Tahoma,sans-serif;min-height:100%}\nbody{padding:0 14px calc(86px + env(safe-area-inset-bottom));background:radial-gradient(900px 420px at 50% -120px,#17307f 0%,transparent 70%),var(--bg)}\nheader{display:flex;align-items:center;gap:12px;padding:16px 2px 10px}\nheader img{width:46px;height:46px;border-radius:12px;box-shadow:0 0 18px #1e6bff88}\nheader .who{flex:1;min-width:0}header .who b{display:block;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\nheader .who span{font-size:12px;color:var(--mut)}\n.bal{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:8px 14px;text-align:center;box-shadow:0 0 14px #1e6bff33}\n.bal b{display:block;font-size:20px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n.bal span{font-size:10px;color:var(--mut)}\n.card{background:linear-gradient(180deg,var(--card),#0d1950);border:1px solid var(--line);border-radius:18px;padding:16px;margin:12px 0}\n.card h3{margin:0 0 10px;font-size:15px}\n.row{display:flex;gap:10px;align-items:center}.row>*{flex:1}\n.btn{border:0;border-radius:13px;padding:13px 16px;font-size:15px;font-weight:700;color:#fff;background:var(--grad);width:100%;cursor:pointer;box-shadow:0 4px 18px #1e6bff55;transition:transform .1s}\n.btn:active{transform:scale(.97)}.btn[disabled]{background:#22315f;color:#7d8cc0;box-shadow:none;cursor:default}\n.btn.ghost{background:transparent;border:1px solid var(--line);box-shadow:none;color:var(--c)}\n.btn.sm{padding:9px 12px;font-size:13px;width:auto;border-radius:10px}\n.mut{color:var(--mut);font-size:12px}.big{font-size:26px;font-weight:800}\n.bar{height:9px;background:#0a1238;border-radius:9px;overflow:hidden;margin:8px 0 4px;border:1px solid var(--line)}\n.bar i{display:block;height:100%;background:var(--grad);border-radius:9px;transition:width .6s}\n.item{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid var(--line);border-radius:14px;margin-top:10px;background:#0c1748}\n.item .ic{font-size:22px}.item .tx{flex:1;min-width:0}.item .tx b{display:block;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pill{background:#0a1238;border:1px solid var(--line);border-radius:20px;padding:3px 10px;font-size:12px;color:var(--c);white-space:nowrap}\n.ad{border:1px dashed #2a4ab8;border-radius:16px;padding:14px;text-align:center;background:repeating-linear-gradient(45deg,#0c1748,#0c1748 10px,#0e1b52 10px,#0e1b52 20px);color:var(--mut)}\n.ad b{display:block;color:var(--tx);margin-bottom:4px}\nnav{position:fixed;left:0;right:0;bottom:0;display:flex;background:#0b1544ee;backdrop-filter:blur(12px);border-top:1px solid var(--line);padding:6px 6px calc(6px + env(safe-area-inset-bottom));z-index:10}\nnav button{flex:1;background:none;border:0;color:var(--mut);font-size:10.5px;padding:6px 0;display:flex;flex-direction:column;align-items:center;gap:2px;cursor:pointer}\nnav button span{font-size:20px;filter:grayscale(.6)}nav button.on{color:var(--c)}nav button.on span{filter:none;text-shadow:0 0 12px var(--c)}\ninput,select{width:100%;background:#0a1238;color:var(--tx);border:1px solid var(--line);border-radius:12px;padding:12px;font-size:15px;margin-top:8px;outline:none}\ninput:focus,select:focus{border-color:var(--b2)}\n#wheelBox{position:relative;width:min(300px,82vw);margin:6px auto 12px;aspect-ratio:1}\n#wheel{width:100%;height:100%;border-radius:50%;box-shadow:0 0 30px #1e6bff77,0 0 0 6px #14267a,0 0 0 8px var(--b2);transition:transform 4.4s cubic-bezier(.12,.7,.1,1)}\n#ptr{position:absolute;top:-12px;left:50%;transform:translateX(-50%);width:0;height:0;border-left:13px solid transparent;border-right:13px solid transparent;border-top:26px solid var(--c);filter:drop-shadow(0 0 8px var(--c));z-index:2}\n#hub{position:absolute;inset:0;margin:auto;width:56px;height:56px;border-radius:50%;background:var(--bg);border:3px solid var(--c);display:flex;align-items:center;justify-content:center;z-index:2;overflow:hidden}\n#hub img{width:100%}\n.lb{display:flex;gap:10px;padding:9px 4px;border-bottom:1px solid #16275f;font-size:14px}.lb:last-child{border:0}.lb .n{width:26px;color:var(--c);font-weight:800}.lb .nm{flex:1}.lb.me{color:var(--c)}\n.tabs{display:flex;gap:8px;margin-bottom:8px}.tabs button{flex:1;padding:9px;border-radius:10px;border:1px solid var(--line);background:none;color:var(--mut);cursor:pointer}.tabs button.on{background:var(--grad);color:#fff;border-color:transparent}\n#toast{position:fixed;top:calc(12px + env(safe-area-inset-top));left:50%;transform:translate(-50%,-90px);background:#0f2a6b;border:1px solid var(--c);color:#fff;padding:11px 18px;border-radius:14px;z-index:99;transition:transform .35s;max-width:90%;text-align:center;font-size:14px;box-shadow:0 0 20px #38e8ff55}\n#toast.show{transform:translate(-50%,0)}\n.modal{position:fixed;inset:0;background:#030820dd;z-index:50;display:none;align-items:center;justify-content:center;padding:20px}.modal.show{display:flex}\n.modal .box{background:var(--card);border:1px solid var(--c);border-radius:20px;padding:20px;width:100%;max-width:360px;text-align:center;box-shadow:0 0 40px #1e6bff77}\n.spin{display:inline-block;width:26px;height:26px;border:3px solid var(--line);border-top-color:var(--c);border-radius:50%;animation:r 1s linear infinite}@keyframes r{to{transform:rotate(360deg)}}\n.center{text-align:center;padding:50px 0}\n</style>\n</head>\n<body>\n<div id="app"><div class="center"><div class="spin"></div></div></div>\n<div id="toast"></div>\n<div class="modal" id="adModal"><div class="box" id="adBox"></div></div>\n<nav id="nav" style="display:none"></nav>\n\n<script>\nconst tg = window.Telegram?.WebApp || {initData:\'\',expand(){},ready(){},HapticFeedback:{impactOccurred(){},notificationOccurred(){}},openLink(u){open(u)},openTelegramLink(u){open(u)},setHeaderColor(){},setBackgroundColor(){},showConfirm(){}};\ntg.ready(); tg.expand();\ntry{tg.setHeaderColor(\'#0a1238\');tg.setBackgroundColor(\'#0a1238\')}catch(e){}\n\nconst I18N = {\nar:{home:\'الرئيسية\',tasks:\'المهام\',wheel:\'العجلة\',friends:\'الأصدقاء\',grow:\'نمّي\',points:\'نقطة\',level:\'المستوى\',\n daily:\'المكافأة اليومية\',claim:\'🎁 استلم المكافأة\',claimed:\'تم الاستلام — عد بعد\',streak:\'أيام متتالية\',\n streak_hint:\'كل يوم متتالي يزيد المكافأة (حتى 7 أيام) + بونص المستوى\',\n xp_next:\'للمستوى التالي\',max_lv:\'أعلى مستوى 👑\',bonus:\'بونص يومي\',\n ad_slot:\'مساحة إعلانية\',ad_soon:\'سيظهر هنا إعلان قريباً\',\n no_tasks:\'لا توجد مهام الآن، عد لاحقاً 🔄\',open:\'فتح\',verify:\'تحقق\',channel:\'قناة\',bot:\'بوت\',\n spin:\'🎡 لف العجلة\',spin_free:\'لفة مجانية جاهزة!\',spin_wait:\'اللفة المجانية القادمة بعد\',spin_extra:\'لفات إضافية\',\n spin_hint:\'لفة مجانية كل 24 ساعة، ولفة إضافية عن كل صديق تدعوه 👥\',won:\'ربحت\',lose:\'حظ أوفر المرة القادمة 🍀\',\n invite:\'ادعُ أصدقاءك\',invite_hint:\'عن كل صديق تحصل على نقاط + لفة عجلة مجانية\',share:\'📤 مشاركة الرابط\',copy:\'📋 نسخ\',copied:\'تم النسخ ✅\',\n refs:\'دعواتك\',week:\'هذا الأسبوع\',all:\'كل الوقت\',lb:\'🏆 المتصدرون\',no_lb:\'لا أحد بعد — كن الأول!\',\n grow_t:\'احصل على متابعين\',grow_hint:\'أنفق نقاطك ليتابع قناتك/بوتك مستخدمون حقيقيون. تبادل متابعين مع باقي المستخدمين.\',\n target:\'@القناة أو رابط البوت\',qty:\'العدد المطلوب\',cost:\'التكلفة\',order:\'🚀 إطلاق الحملة\',my_orders:\'حملاتك\',\n ad_title:\'📺 إعلان\',ad_open:\'افتح الإعلان\',ad_wait:\'انتظر\',ad_claim:\'🎁 استلم النقاط\',ad_close:\'إغلاق\',\n gate_t:\'🔒 أكمل هذه الخطوات لاستخدام التطبيق\',\n done:\'✅ تمت إضافة\',\n e_auth:\'افتح التطبيق من داخل تيليجرام\',e_nouser:\'أرسل /start للبوت أولاً\',e_banned:\'حسابك محظور\',e_server:\'خطأ بالخادم، حاول لاحقاً\',\n e_daily_wait:\'المكافأة غير جاهزة بعد\',e_spin_wait:\'لا توجد لفات متاحة الآن\',\n e_task_not_joined:\'لم تنضم بعد ❌\',e_task_wait:\'انتظر قليلاً ثم أعد المحاولة ⏳\',e_task_already:\'أكملتها سابقاً\',e_task_full:\'المهمة اكتملت\',e_task_gone:\'المهمة غير متاحة\',\n e_bad_target:\'الرابط/المعرف غير صالح\',e_bad_qty:\'عدد غير صالح\',e_not_admin:\'أضف البوت كأدمن في القناة أولاً\',e_no_points:\'رصيدك لا يكفي\',\n e_ad_wait:\'لم يحن وقت الإعلان بعد\',e_ad_gone:\'الإعلان غير متاح\',e_ad_early:\'لم تكمل مدة المشاهدة بعد\',\n gate_fail:\'لم تكمل كل الخطوات بعد ❌\'},\nen:{home:\'Home\',tasks:\'Tasks\',wheel:\'Wheel\',friends:\'Friends\',grow:\'Grow\',points:\'points\',level:\'Level\',\n daily:\'Daily bonus\',claim:\'🎁 Claim reward\',claimed:\'Claimed — come back in\',streak:\'day streak\',\n streak_hint:\'Each consecutive day raises the reward (up to 7 days) + level bonus\',\n xp_next:\'to next level\',max_lv:\'Max level 👑\',bonus:\'daily bonus\',\n ad_slot:\'Ad space\',ad_soon:\'An ad will appear here soon\',\n no_tasks:\'No tasks right now, check back later 🔄\',open:\'Open\',verify:\'Verify\',channel:\'Channel\',bot:\'Bot\',\n spin:\'🎡 Spin the wheel\',spin_free:\'Free spin ready!\',spin_wait:\'Next free spin in\',spin_extra:\'extra spins\',\n spin_hint:\'One free spin every 24h, plus an extra spin for every friend you invite 👥\',won:\'You won\',lose:\'Better luck next time 🍀\',\n invite:\'Invite friends\',invite_hint:\'Earn points + a free wheel spin for every friend\',share:\'📤 Share link\',copy:\'📋 Copy\',copied:\'Copied ✅\',\n refs:\'Your invites\',week:\'This week\',all:\'All time\',lb:\'🏆 Leaderboard\',no_lb:\'Nobody yet — be the first!\',\n grow_t:\'Get followers\',grow_hint:\'Spend points so real users follow your channel/bot. Swap followers with other users.\',\n target:\'@channel or bot link\',qty:\'Amount\',cost:\'Cost\',order:\'🚀 Launch campaign\',my_orders:\'Your campaigns\',\n ad_title:\'📺 Sponsored\',ad_open:\'Open ad\',ad_wait:\'Wait\',ad_claim:\'🎁 Claim points\',ad_close:\'Close\',\n gate_t:\'🔒 Complete these steps to use the app\',\n done:\'✅ Added\',\n e_auth:\'Open the app from inside Telegram\',e_nouser:\'Send /start to the bot first\',e_banned:\'Your account is banned\',e_server:\'Server error, try later\',\n e_daily_wait:\'Reward not ready yet\',e_spin_wait:\'No spins available now\',\n e_task_not_joined:"You haven\'t joined yet ❌",e_task_wait:\'Wait a moment and retry ⏳\',e_task_already:\'Already completed\',e_task_full:\'Task is full\',e_task_gone:\'Task unavailable\',\n e_bad_target:\'Invalid link/username\',e_bad_qty:\'Invalid amount\',e_not_admin:\'Add the bot as admin in the channel first\',e_no_points:\'Not enough points\',\n e_ad_wait:\'Not time for an ad yet\',e_ad_gone:\'Ad unavailable\',e_ad_early:\'Watch time not finished\',\n gate_fail:\'You have not completed all steps ❌\'}\n};\nlet L=\'en\', S={me:null,tab:\'home\',tasks:null,lb:null,lbTab:\'weekly\',orders:[],busy:{}};\nconst t=k=>(I18N[L]&&I18N[L][k])||I18N.en[k]||k;\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst fmt=s=>{s=Math.max(0,Math.floor(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h?`${h}h ${m}m`:`${m}m ${s%60}s`};\nfunction toast(m){const e=$(\'#toast\');e.textContent=m;e.classList.add(\'show\');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove(\'show\'),2600)}\nconst hap=(k=\'success\')=>{try{tg.HapticFeedback.notificationOccurred(k)}catch(e){}};\n\nasync function api(path,body={}){\n  let r,j;\n  try{r=await fetch(\'/api/\'+path,{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-Init-Data\':tg.initData},body:JSON.stringify(body)});j=await r.json()}\n  catch(e){j={error:\'server\'}}\n  if(j.error===\'gate\'){S.me=S.me||{};S.me.gate=j.tasks;render();}\n  return j;\n}\nconst err=j=>{const m=t(\'e_\'+j.error);toast(m!==\'e_\'+j.error?m:j.error);hap(\'error\')};\nasync function once(key,fn){if(S.busy[key])return;S.busy[key]=1;try{await fn()}finally{S.busy[key]=0}}\n\nasync function loadMe(){const j=await api(\'me\');if(j.error){document.getElementById(\'app\').innerHTML=`<div class="center">${esc(t(\'e_\'+j.error))}</div>`;return false}\n  S.me=j;L=[\'ar\'].includes(j.lang)?\'ar\':\'en\';document.documentElement.lang=L;document.documentElement.dir=L===\'ar\'?\'rtl\':\'ltr\';return true}\n\nfunction header(){const m=S.me;return `<header><img src="/logo.jpg" alt=""><div class="who"><b>${esc(m.name)}</b><span>${m.level.icon} ${m.level.name}</span></div>\n<div class="bal"><b id="pts">${m.points}</b><span>${t(\'points\')}</span></div></header>`}\n\nfunction adSlot(){return `<div class="ad"><b>📢 ${t(\'ad_slot\')}</b>${t(\'ad_soon\')}</div>`}\n\nfunction renderNav(){const tabs=[[\'home\',\'🏠\'],[\'tasks\',\'✅\'],[\'wheel\',\'🎡\'],[\'friends\',\'👥\'],[\'grow\',\'🚀\']];\n  const n=$(\'#nav\');n.style.display=\'flex\';n.innerHTML=tabs.map(([k,i])=>`<button class="${S.tab===k?\'on\':\'\'}" onclick="go(\'${k}\')"><span>${i}</span>${t(k)}</button>`).join(\'\')}\nfunction go(k){S.tab=k;render();try{tg.HapticFeedback.impactOccurred(\'light\')}catch(e){}}\n\nfunction render(){\n  const m=S.me,app=$(\'#app\');if(!m)return;\n  if(m.gate&&m.gate.length){$(\'#nav\').style.display=\'none\';\n    app.innerHTML=header()+`<div class="card"><h3>${t(\'gate_t\')}</h3>`+m.gate.map(g=>`<div class="item"><div class="ic">${g.type===\'channel\'?\'📢\':\'🤖\'}</div><div class="tx"><b>${esc(g.name)}</b><span class="mut">${esc(g.descr||\'\')}</span></div><button class="btn sm" onclick="gateOpen(${g.id},\'${esc(g.link)}\')">${t(\'open\')}</button></div>`).join(\'\')+`<button class="btn" style="margin-top:14px" onclick="gateVerify()">${t(\'verify\')}</button></div>`;return}\n  renderNav();\n  ({home:vHome,tasks:vTasks,wheel:vWheel,friends:vFriends,grow:vGrow})[S.tab]();\n}\nasync function gateOpen(id,l){await api(\'gate/open\',{id});tg.openLink(l)}\nasync function gateVerify(){const j=await api(\'gate/verify\');if(j.gate&&j.gate.length){S.me.gate=j.gate;toast(t(\'gate_fail\'));render()}else{await loadMe();render()}}\n\n/* ───── Home ───── */\nlet dailyTimer;\nfunction vHome(){\n  const m=S.me,lv=m.level;\n  const pct=lv.next?Math.min(100,(lv.xp-lv.from)/(lv.next-lv.from)*100):100;\n  $(\'#app\').innerHTML=header()+`\n  <div class="card"><div class="row"><div><h3>${t(\'daily\')}</h3><div class="mut">${t(\'streak_hint\')}</div></div>\n    <div style="flex:0 0 auto;text-align:center"><div class="big">🔥${m.streak}</div><div class="mut">${t(\'streak\')}</div></div></div>\n    <button class="btn" id="dailyBtn" style="margin-top:12px" onclick="claimDaily()"></button></div>\n  <div class="card"><h3>${lv.icon} ${t(\'level\')}: ${lv.name} <span class="pill">+${lv.bonus}% ${t(\'bonus\')}</span></h3>\n    <div class="bar"><i style="width:${pct}%"></i></div>\n    <div class="mut">${lv.next?`XP ${lv.xp} / ${lv.next} — ${lv.next-lv.xp} ${t(\'xp_next\')}`:t(\'max_lv\')}</div></div>\n  <div class="row"><div class="card" style="margin:0;text-align:center"><div class="big">${m.tasks_done}</div><div class="mut">${t(\'tasks\')}</div></div>\n    <div class="card" style="margin:0;text-align:center"><div class="big">${m.referrals}</div><div class="mut">${t(\'refs\')}</div></div></div>\n  <div style="margin-top:12px" id="adSlot">${adSlot()}</div>`;\n  tickDaily();\n}\nfunction tickDaily(){clearInterval(dailyTimer);const b=$(\'#dailyBtn\');if(!b)return;\n  const u=()=>{const w=S.me.daily_wait;if(w>0){b.disabled=true;b.textContent=`${t(\'claimed\')} ${fmt(w)}`;S.me.daily_wait--}else{b.disabled=false;b.textContent=t(\'claim\');clearInterval(dailyTimer)}};u();dailyTimer=setInterval(()=>{if(!$(\'#dailyBtn\'))return clearInterval(dailyTimer);u()},1000)}\nfunction setPoints(p){S.me.points=p;const e=$(\'#pts\');if(e)e.textContent=p}\nfunction claimDaily(){once(\'daily\',async()=>{const j=await api(\'daily\');if(j.error)return err(j);\n  S.me=j.me;S.me.gate=[];hap();toast(`🎁 +${j.reward} ${t(\'points\')}  🔥${j.streak}`);render()})}\n\n/* ───── Tasks ───── */\nasync function vTasks(){\n  $(\'#app\').innerHTML=header()+`<div class="card"><h3>✅ ${t(\'tasks\')}</h3><div id="tl"><div class="center"><div class="spin"></div></div></div></div><div id="adSlot">${adSlot()}</div>`;\n  const j=await api(\'tasks\');if(j.error)return;S.tasks=j.tasks;drawTasks();\n}\nfunction drawTasks(){const el=$(\'#tl\');if(!el)return;\n  el.innerHTML=S.tasks.length?S.tasks.map(k=>`<div class="item" id="tk${k.id}"><div class="ic">${k.type===\'channel\'?\'📢\':\'🤖\'}</div>\n   <div class="tx"><b>${esc(k.name)}</b><span class="mut">${t(k.type)} · ${esc(k.descr||\'\')}</span></div>\n   <span class="pill">+${k.reward}</span>\n   <button class="btn sm ghost" onclick="openTask(${k.id})">${t(\'open\')}</button>\n   <button class="btn sm" onclick="doneTask(${k.id})">${t(\'verify\')}</button></div>`).join(\'\'):`<div class="mut center" style="padding:24px 0">${t(\'no_tasks\')}</div>`}\nasync function openTask(id){const k=S.tasks.find(x=>x.id===id);await api(\'task/open\',{id});tg.openLink(k.link)}\nfunction doneTask(id){once(\'t\'+id,async()=>{const j=await api(\'task/done\',{id});\n  if(j.error){if([\'task_already\',\'task_full\',\'task_gone\'].includes(j.error)){S.tasks=S.tasks.filter(x=>x.id!==id);drawTasks()}\n    return err(j)}\n  hap();toast(`+${j.reward} ${t(\'points\')} ✅`);setPoints(j.points);S.tasks=S.tasks.filter(x=>x.id!==id);drawTasks()})}\n\n/* ───── Wheel ───── */\nlet rot=0;\nfunction vWheel(){\n  const m=S.me,sp=m.spin;\n  $(\'#app\').innerHTML=header()+`<div class="card" style="text-align:center"><h3>🎡 ${t(\'wheel\')}</h3>\n   <div id="wheelBox"><div id="ptr"></div><canvas id="wheel" width="600" height="600" style="transform:rotate(${rot}deg)"></canvas><div id="hub"><img src="/logo.jpg"></div></div>\n   <div id="spinInfo" class="mut" style="margin-bottom:10px"></div>\n   <button class="btn" id="spinBtn" onclick="doSpin()"></button>\n   <div class="mut" style="margin-top:10px">${t(\'spin_hint\')}</div></div>`;\n  drawWheel();spinUI()}\nfunction spinUI(){const sp=S.me.spin,b=$(\'#spinBtn\'),i=$(\'#spinInfo\');if(!b)return;\n  const can=sp.free||sp.extra>0;b.disabled=!can||S.busy.spin;b.textContent=t(\'spin\');\n  i.textContent=(sp.free?t(\'spin_free\'):`${t(\'spin_wait\')} ${fmt(sp.wait)}`)+(sp.extra?`  ·  +${sp.extra} ${t(\'spin_extra\')}`:\'\')}\nfunction drawWheel(){const c=$(\'#wheel\');if(!c)return;const x=c.getContext(\'2d\'),P=S.me.wheel,n=P.length,R=300,a=2*Math.PI/n;\n  const cols=[\'#1e6bff\',\'#1593ff\',\'#0f4fd6\',\'#2ab6ff\'];\n  P.forEach((p,i)=>{x.beginPath();x.moveTo(R,R);x.arc(R,R,R,i*a-Math.PI/2,(i+1)*a-Math.PI/2);x.closePath();x.fillStyle=cols[i%4];x.fill();x.strokeStyle=\'#0a1238\';x.lineWidth=4;x.stroke();\n    x.save();x.translate(R,R);x.rotate(i*a+a/2);x.fillStyle=\'#fff\';x.font=\'bold 44px system-ui\';x.textAlign=\'center\';x.shadowColor=\'#0008\';x.shadowBlur=6;\n    x.fillText(p?(\'+\'+p):\'✖\',0,-R+82);x.restore()})}\nfunction doSpin(){once(\'spin\',async()=>{const b=$(\'#spinBtn\');b.disabled=true;const j=await api(\'spin\');if(j.error){err(j);return spinUI()}\n  const n=S.me.wheel.length,seg=360/n;rot=(Math.floor(rot/360)+6)*360+(360-(j.index*seg+seg/2));\n  const c=$(\'#wheel\');c.style.transform=`rotate(${rot}deg)`;\n  await new Promise(r=>setTimeout(r,4500));\n  S.me.spin=j.spin;setPoints(j.points);\n  if(j.prize){hap();toast(`🎉 ${t(\'won\')} +${j.prize} ${t(\'points\')}`)}else toast(t(\'lose\'));\n  spinUI()})}\n\n/* ───── Friends ───── */\nasync function vFriends(){\n  const m=S.me;\n  $(\'#app\').innerHTML=header()+`<div class="card"><h3>👥 ${t(\'invite\')}</h3><div class="mut">${t(\'invite_hint\')} (+${m.ref_bonus})</div>\n   <input readonly value="${esc(m.ref_link)}" onclick="this.select()"><div class="row" style="margin-top:10px"><button class="btn" onclick="shareRef()">${t(\'share\')}</button><button class="btn ghost" onclick="copyRef()">${t(\'copy\')}</button></div>\n   <div class="mut" style="margin-top:10px">${t(\'refs\')}: <b style="color:var(--c)">${m.referrals}</b></div></div>\n  <div class="card"><h3>${t(\'lb\')}</h3><div class="tabs"><button id="tw" onclick="lbTab(\'weekly\')">${t(\'week\')}</button><button id="ta" onclick="lbTab(\'all\')">${t(\'all\')}</button></div><div id="lbl"><div class="center"><div class="spin"></div></div></div></div>`;\n  const j=await api(\'leaderboard\');if(j.error)return;S.lb=j;lbTab(S.lbTab)}\nfunction lbTab(k){S.lbTab=k;$(\'#tw\')?.classList.toggle(\'on\',k===\'weekly\');$(\'#ta\')?.classList.toggle(\'on\',k===\'all\');\n  const rows=S.lb?S.lb[k]:[];const e=$(\'#lbl\');if(!e)return;\n  e.innerHTML=rows.length?rows.map((r,i)=>`<div class="lb ${r.me?\'me\':\'\'}"><div class="n">${[\'🥇\',\'🥈\',\'🥉\'][i]||i+1}</div><div class="nm">${esc(r.name)}</div><div>${r.n} 👥</div></div>`).join(\'\'):`<div class="mut center" style="padding:20px 0">${t(\'no_lb\')}</div>`}\nfunction shareRef(){const m=S.me;tg.openTelegramLink(\'https://t.me/share/url?url=\'+encodeURIComponent(m.ref_link)+\'&text=\'+encodeURIComponent(L===\'ar\'?\'🚀 انضم واربح نقاط مجانية!\':\'🚀 Join and earn free points!\'))}\nasync function copyRef(){try{await navigator.clipboard.writeText(S.me.ref_link);toast(t(\'copied\'))}catch(e){const i=$(\'input\');i.select();document.execCommand(\'copy\');toast(t(\'copied\'))}}\n\n/* ───── Grow ───── */\nasync function vGrow(){\n  const m=S.me;\n  $(\'#app\').innerHTML=header()+`<div class="card"><h3>🚀 ${t(\'grow_t\')}</h3><div class="mut">${t(\'grow_hint\')}</div>\n   <select id="gk"><option value="channel">📢 ${t(\'channel\')}</option><option value="bot">🤖 ${t(\'bot\')}</option></select>\n   <input id="gt" placeholder="${t(\'target\')}" dir="ltr" autocomplete="off"><input id="gq" type="number" inputmode="numeric" min="1" placeholder="${t(\'qty\')}" oninput="upCost()">\n   <div class="row" style="margin:10px 0"><span class="mut">${t(\'cost\')}</span><b id="gc" style="text-align:end;color:var(--c)">0</b></div>\n   <button class="btn" onclick="doOrder()">${t(\'order\')}</button></div>\n   <div class="card"><h3>${t(\'my_orders\')}</h3><div id="ol"><div class="center"><div class="spin"></div></div></div></div>`;\n  const j=await api(\'orders\');if(j.error)return;const e=$(\'#ol\');if(!e)return;\n  e.innerHTML=j.orders.length?j.orders.map(o=>`<div class="item"><div class="ic">${o.type===\'channel\'?\'📢\':\'🤖\'}</div><div class="tx"><b>${esc(o.name)}</b><div class="bar"><i style="width:${Math.min(100,o.done/o.total*100)}%"></i></div></div><span class="pill">${o.done}/${o.total}</span></div>`).join(\'\'):\'<div class="mut">—</div>\'}\nfunction upCost(){const q=parseInt($(\'#gq\').value)||0;$(\'#gc\').textContent=q*S.me.cost}\nfunction doOrder(){once(\'order\',async()=>{const j=await api(\'order\',{kind:$(\'#gk\').value,target:$(\'#gt\').value,qty:parseInt($(\'#gq\').value)||0});\n  if(j.error)return err(j);hap();toast(`${t(\'done\')} ${j.target}`);setPoints(j.points);vGrow()})}\n\n/* ───── Ads: تظهر بعد مدة، ومكانها محجوز إلى أن تُضاف الروابط من لوحة الأدمن ───── */\nlet adBusy=false,nextAd=Date.now()+60000,adCd;\nasync function adCheck(){\n  if(adBusy||!S.me||(S.me.gate&&S.me.gate.length)||document.hidden||Date.now()<nextAd)return;\n  const j=await api(\'ad/next\');\n  if(!j||j.error){return}\n  if(!j.ad){nextAd=Date.now()+(j.wait?j.wait*1000+2000:S.me.ad_interval*1000);return}\n  showAd(j.ad,j.watch)}\nfunction showAd(ad,watch){adBusy=true;$(\'#adModal\').classList.add(\'show\');\n  $(\'#adBox\').innerHTML=`<div class="mut">${t(\'ad_title\')}</div><h3 style="margin:8px 0">${esc(ad.title)}</h3><div class="pill" style="display:inline-block;margin-bottom:14px">+${ad.reward} ${t(\'points\')}</div>\n   <button class="btn" id="adGo">${t(\'ad_open\')}</button><button class="btn ghost" id="adX" style="margin-top:10px">${t(\'ad_close\')}</button>`;\n  $(\'#adX\').onclick=closeAd;\n  $(\'#adGo\').onclick=async()=>{const b=$(\'#adGo\');b.disabled=true;const j=await api(\'ad/start\',{id:ad.id});if(j.error){err(j);return closeAd()}\n    tg.openLink(j.url);let left=j.watch;b.textContent=`${t(\'ad_wait\')} ${left}s`;\n    adCd=setInterval(()=>{left--;if(left>0){b.textContent=`${t(\'ad_wait\')} ${left}s`;return}clearInterval(adCd);b.disabled=false;b.textContent=t(\'ad_claim\');\n      b.onclick=async()=>{b.disabled=true;const r=await api(\'ad/claim\',{view:j.view});if(r.error){err(r);return closeAd()}hap();toast(`+${r.reward} ${t(\'points\')} 🎉`);setPoints(r.points);closeAd()}},1000)}}\nfunction closeAd(){clearInterval(adCd);$(\'#adModal\').classList.remove(\'show\');adBusy=false;nextAd=Date.now()+(S.me?S.me.ad_interval:600)*1000}\n\n(async()=>{if(await loadMe()){render();setInterval(adCheck,20000)}})();\n</script>\n</body>\n</html>\n'
